var i=`0431-kladdkaka`;var n=`world-0431`;var o=`SE`;var a=`northern-europe`;var r=8;var l=77;var d={en:`Kladdkaka`,ua:`Кладкака`};var g={en:`A traditional dish from Sweden, centered on chicken egg, all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Швеція. Основні складники: куряче яйце, пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var s=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`unsalted-butter`,145,`g`],[`white-granulated-sugar`,245,`g`],[`chicken-egg`,2,`pcs`],[`vanilla-extract`,5,`ml`]]},{en:`Gently fold in the remaining dry or wet ingredients just until homogeneous, without deflating the mixture.`,ua:`Обережно вмішайте решту сухих або рідких складників лише до однорідності, не осаджуючи масу.`,t:[`folding-batter`],m:5,i:[[`all-purpose-flour`,100,`g`],[`cocoa-powder`,45,`g`],[`table-salt`,2,`g`]]},{en:`Bake at 175°C only until the edges set while the center stays visibly soft and fudgy. Cool before slicing; avoid overbaking.`,ua:`Випікайте при 175°C лише до схоплення країв, залишивши центр вологим і тягучим. Остудіть перед нарізанням; не пересушуйте.`,t:[`baking`],m:20,i:[]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[]}];var u={slug:i,id:n,country:`SE`,region:a,servings:8,minutes:77,title:d,text:g,steps:s};export{o as country,u as default,n as id,l as minutes,a as region,r as servings,i as slug,s as steps,g as text,d as title};